import json, subprocess, sys
from datetime import datetime, timezone

REPO = "seungpyoson/bolt-v2"

def gh(path):
    out = subprocess.run(["gh", "api", path], capture_output=True, text=True)
    if out.returncode != 0:
        print("ERR", path, out.stderr[:300]); sys.exit(1)
    return json.loads(out.stdout)

def ts(s):
    return datetime.fromisoformat(s.replace("Z", "+00:00"))

# Recent runs across all workflows on merge-queue branches
runs = []
for page in (1, 2, 3):
    data = gh(f"repos/{REPO}/actions/runs?per_page=100&page={page}&created=>=2026-06-30")
    for r in data.get("workflow_runs", []):
        hb = r.get("head_branch") or ""
